package runtimestate

// G5 PR 1a.1 characterization baseline (issue #1147).
//
// These tests pin the CURRENT persisted runtime-state bytes, with and without
// opaque (independent plugin) namespaces, and the current instance-GUID
// behaviour: the GUID is never derived or generated by this package; it is
// either supplied by the caller (EagerPersistInstanceGUID) or carried over
// verbatim from the loaded file. Later G5 PRs (1b durable control in
// particular) may legitimately change these bytes; each pinned value names the
// change that would alter it and the PR must justify the difference.
//
// Regeneration: expectations are inline. On mismatch the test prints the full
// observed bytes between "--- observed ---" markers for review and paste-back:
//
//	go test ./internal/runtimestate -run Characterization -count=1 -v
//
// Determinism: written_at is stamped from the wall clock by production code
// (no clock seam exists). The tests assert it parses as RFC 3339 UTC and then
// replace it with the placeholder <written_at> before comparing; nothing else
// depends on time. All fixtures are synthetic.

import (
	"context"
	"encoding/json"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"sync"
	"testing"
	"time"
)

const (
	ctlGUIDPrimary   = "00000000-0000-4000-8000-000000000001"
	ctlGUIDSecondary = "00000000-0000-4000-8000-000000000002"
)

// ctlCaptureHooks delegates to the production filesystem hooks and records
// every staged payload so the exact persisted bytes are observable.
type ctlCaptureHooks struct {
	DefaultFilesystemHooks
	mu     sync.Mutex
	writes [][]byte
}

func (hooks *ctlCaptureHooks) WriteFile(path string, data []byte, perm uint32) error {
	hooks.mu.Lock()
	hooks.writes = append(hooks.writes, append([]byte(nil), data...))
	hooks.mu.Unlock()
	return hooks.DefaultFilesystemHooks.WriteFile(path, data, perm)
}

func (hooks *ctlCaptureHooks) take() [][]byte {
	hooks.mu.Lock()
	defer hooks.mu.Unlock()
	writes := hooks.writes
	hooks.writes = nil
	return writes
}

var ctlWrittenAtPattern = regexp.MustCompile(`"written_at": ?"([^"]*)"`)

// ctlNormalizeWrittenAt asserts every written_at value is RFC 3339 UTC and
// replaces it with a stable placeholder.
func ctlNormalizeWrittenAt(t *testing.T, data []byte) string {
	t.Helper()
	return ctlWrittenAtPattern.ReplaceAllStringFunc(string(data), func(match string) string {
		value := ctlWrittenAtPattern.FindStringSubmatch(match)[1]
		parsed, err := time.Parse(time.RFC3339Nano, value)
		if err != nil || parsed.Location() != time.UTC || !strings.HasSuffix(value, "Z") {
			t.Errorf("written_at %q is not RFC 3339 UTC: %v", value, err)
		}
		return strings.Replace(match, value, "<written_at>", 1)
	})
}

func requireCtlText(t *testing.T, label, got, want, changesBy string) {
	t.Helper()
	if got == want {
		return
	}
	t.Errorf("%s drifted (changes when: %s)\n--- want ---\n%s\n--- observed ---\n%s--- observed ---", label, changesBy, want, got)
}

func ctlFixtureState() *State {
	companion := byte(0x1F)
	memberCompanion := byte(0x2F)
	at := time.Date(2001, 2, 3, 4, 5, 6, 0, time.UTC)
	return &State{
		SchemaVersion: SchemaVersion,
		Meta: Meta{
			InstanceGUID: ctlGUIDPrimary,
			WrittenAt:    at,
			GatewayBuild: "char-build",
			AddonVersion: "0.0.0-char",
		},
		EBus: &EBusNamespace{
			SchemaVersion: EBusSchemaVersion,
			Self: &Self{
				LastAdmittedSource: 0x1A,
				LastAdmittedAt:     at,
				SelectionMethod:    SelectionMethodWarmup,
				CompanionTarget:    &companion,
			},
			KnownBusMembers: []KnownBusMember{
				{Addr: 0x2A, CompanionAddr: &memberCompanion, Identity: &Identity{Manufacturer: "synthetic", DeviceID: "FAMA"}, LastSeenAt: at, LastSource: LastSourcePassiveObserved, Confidence: ConfidenceCorroborated},
				{Addr: 0x3A, LastSeenAt: at.Add(time.Second), LastSource: LastSourceNMEvent, Confidence: ConfidenceUnidentified},
			},
		},
	}
}

