// ctlOpaqueInput is a synthetic on-disk file carrying two independent plugin
// namespaces around the typed ones, in deliberately unsorted order.
const ctlOpaqueInput = `{
  "zeta_plugin": {"schema_version": 3, "nested": {"b": 2, "a": [1, 2]}},
  "schema_version": 1,
  "meta": {"instance_guid": "00000000-0000-4000-8000-000000000001", "written_at": "2001-02-03T04:05:06Z", "gateway_build": "old-build"},
  "ebus": {"schema_version": 1, "self": {"last_admitted_source": 26, "last_admitted_at": "2001-02-03T04:05:06Z", "selection_method": "explicit_validate_only", "companion_target": null}},
  "alpha_plugin": ["opaque", true, null]
}
`

const ctlBytesWithOpaque = `{
  "alpha_plugin": [
    "opaque",
    true,
    null
  ],
  "ebus": {
    "schema_version": 1,
    "self": {
      "last_admitted_source": 26,
      "last_admitted_at": "2001-02-03T04:05:06Z",
      "selection_method": "explicit_validate_only",
      "companion_target": null
    }
  },
  "meta": {
    "instance_guid": "00000000-0000-4000-8000-000000000001",
    "written_at": "<written_at>",
    "gateway_build": "char-build",
    "addon_version": "0.0.0-char"
  },
  "schema_version": 1,
  "zeta_plugin": {
    "schema_version": 3,
    "nested": {
      "b": 2,
      "a": [
        1,
        2
      ]
    }
  }
}
`

// TestControlCharacterizationMarshalBytesWithoutOpaqueNamespaces pins the
// historical struct-ordered encoding used when no plugin namespace exists.
func TestControlCharacterizationMarshalBytesWithoutOpaqueNamespaces(t *testing.T) {
	data, err := marshalState(ctlFixtureState())
	if err != nil {
		t.Fatalf("marshalState() error = %v", err)
	}
	// Changes when: 1b durable control adds a namespace (for example persisted
	// desired driver state) or reorders/renames current-v1 fields.
	requireCtlText(t, "current-v1 bytes", string(data), ctlBytesWithoutOpaque,
		"1b durable control adds persisted control fields or changes the v1 field order")
}

// TestControlCharacterizationOpaqueNamespacesRoundTripThroughManager pins the
// sorted-map encoding used once any opaque namespace was loaded, and that a
// startup metadata flush rewrites only meta while carrying plugin values and
// the loaded GUID verbatim.
func TestControlCharacterizationOpaqueNamespacesRoundTripThroughManager(t *testing.T) {
	path := filepath.Join(t.TempDir(), "runtime_state.json")
	if err := os.WriteFile(path, []byte(ctlOpaqueInput), 0o600); err != nil {
		t.Fatalf("write fixture: %v", err)
	}
	hooks := &ctlCaptureHooks{}
	manager := New(Options{Path: path, GatewayBuild: "char-build", AddonVersion: "0.0.0-char", FsHooks: hooks})
	state, err := manager.Load(context.Background())
	if err != nil {
		t.Fatalf("Load() error = %v", err)
	}
	// Changes when: 1b durable control promotes or validates plugin namespaces
	// instead of keeping them private and opaque.
	if got := len(state.opaqueNamespaces); got != 2 {
		t.Errorf("opaque namespaces = %d, want 2 (changes when: 1b promotes plugin namespaces)", got)
	}
	if err := manager.Flush(context.Background()); err != nil {
		t.Fatalf("Flush() error = %v", err)
	}
	writes := hooks.take()
	// Changes when: 1b durable control persists more or fewer times at
	// startup (today exactly one metadata flush because the build differs).
	if len(writes) != 1 {
		t.Fatalf("startup flush writes = %d, want 1 (changes when: 1b changes startup persistence)", len(writes))
	}
	requireCtlText(t, "opaque round-trip bytes", ctlNormalizeWrittenAt(t, writes[0]), ctlBytesWithOpaque,
		"1b durable control changes the opaque-namespace encoding, key order or meta rewrite")
	onDisk, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read persisted file: %v", err)
	}
	// Changes when: the atomic temp+rename contract changes (staged bytes and
	// final bytes must be identical today).
	if string(onDisk) != string(writes[0]) {
		t.Errorf("final file differs from staged bytes (changes when: atomic write contract changes)")
	}
}

// TestControlCharacterizationUnsupportedEBusVersionDropsOnlyEBus pins that a
// future ebus schema drops the typed eBUS namespace while plugin namespaces
// survive the next persist.
func TestControlCharacterizationUnsupportedEBusVersionDropsOnlyEBus(t *testing.T) {
	path := filepath.Join(t.TempDir(), "runtime_state.json")
	input := strings.Replace(ctlOpaqueInput, `"ebus": {"schema_version": 1,`, `"ebus": {"schema_version": 9,`, 1)
	if err := os.WriteFile(path, []byte(input), 0o600); err != nil {
		t.Fatalf("write fixture: %v", err)
	}
	hooks := &ctlCaptureHooks{}
	manager := New(Options{Path: path, GatewayBuild: "char-build", AddonVersion: "0.0.0-char", FsHooks: hooks})
	if _, err := manager.Load(context.Background()); err != nil {
		t.Fatalf("Load() error = %v", err)
	}
	if err := manager.Flush(context.Background()); err != nil {
		t.Fatalf("Flush() error = %v", err)
	}
	writes := hooks.take()
	if len(writes) != 1 {
		t.Fatalf("writes = %d, want 1", len(writes))
	}
	var root map[string]json.RawMessage
	if err := json.Unmarshal(writes[0], &root); err != nil {
		t.Fatalf("persisted bytes are not JSON: %v", err)
	}
	keys := make([]string, 0, len(root))
	for key := range root {
		keys = append(keys, key)
	}
	got := strings.Join(ctlSorted(keys), ",")
	// Changes when: 1b durable control migrates or retains unsupported ebus
	// payloads instead of dropping them (AD12 today).
	requireCtlText(t, "top-level keys", got, "alpha_plugin,meta,schema_version,zeta_plugin",
		"1b durable control retains or migrates an unsupported ebus namespace")
}

// TestControlCharacterizationInstanceGUIDIsCarriedNeverDerived pins the
// current GUID lifecycle across load, startup flush and eager persist.
func TestControlCharacterizationInstanceGUIDIsCarriedNeverDerived(t *testing.T) {
	type observation struct {
		label     string
		got       string
		want      string
		changesBy string
	}
	var observations []observation
	guidOf := func(t *testing.T, data []byte) string {
		t.Helper()
		var file struct {
			Meta struct {
				InstanceGUID *string `json:"instance_guid"`
			} `json:"meta"`
		}
		if err := json.Unmarshal(data, &file); err != nil {
			t.Fatalf("persisted bytes are not JSON: %v", err)
		}
		if file.Meta.InstanceGUID == nil {
			return "<absent>"
		}
		if *file.Meta.InstanceGUID == "" {
			return "<empty>"
		}
		return *file.Meta.InstanceGUID
	}

	t.Run("loaded_guid_survives_startup_flush_then_eager_persist_overrides", func(t *testing.T) {
		path := filepath.Join(t.TempDir(), "runtime_state.json")
		if err := os.WriteFile(path, []byte(ctlOpaqueInput), 0o600); err != nil {
			t.Fatalf("write fixture: %v", err)
		}
		hooks := &ctlCaptureHooks{}
		manager := New(Options{Path: path, GatewayBuild: "char-build", FsHooks: hooks})
		state, _ := manager.Load(context.Background())
		_ = manager.Flush(context.Background())
		flushed := hooks.take()
		observations = append(observations,
			observation{"loaded state GUID", state.Meta.InstanceGUID, ctlGUIDPrimary, "1b durable control derives or validates the GUID on load"},
			observation{"startup flush GUID", guidOf(t, flushed[0]), ctlGUIDPrimary, "1b durable control regenerates the GUID on startup"},
		)
		if err := manager.EagerPersistInstanceGUID(context.Background(), ctlGUIDSecondary, IdentitySourceCLIOverride); err != nil {
			t.Fatalf("EagerPersistInstanceGUID() error = %v", err)
		}
		eager := hooks.take()
		observations = append(observations,
			observation{"eager persist writes", strings.Repeat("w", len(eager)), "w", "1b durable control batches eager persistence"},
			observation{"eager persist GUID", guidOf(t, eager[0]), ctlGUIDSecondary, "1b durable control refuses to replace a persisted GUID with a different supplied one"},
			observation{"in-memory GUID", manager.State().Meta.InstanceGUID, ctlGUIDSecondary, "1b durable control keeps the loaded GUID authoritative"},
		)
	})

	t.Run("no_file_no_supplied_guid_persists_empty_guid", func(t *testing.T) {
		path := filepath.Join(t.TempDir(), "runtime_state.json")
		hooks := &ctlCaptureHooks{}
		manager := New(Options{Path: path, GatewayBuild: "char-build", FsHooks: hooks})
		_, _ = manager.Load(context.Background())
		_ = manager.Flush(context.Background())
		writes := hooks.take()
		got := "<no write>"
		if len(writes) == 1 {
			got = guidOf(t, writes[0])
		}
		observations = append(observations,
			observation{"fresh install GUID", got, "<empty>", "1b durable control generates a GUID when none is supplied or persisted"})
	})

	t.Run("no_file_no_build_metadata_writes_nothing", func(t *testing.T) {
		path := filepath.Join(t.TempDir(), "runtime_state.json")
		hooks := &ctlCaptureHooks{}
		manager := New(Options{Path: path, FsHooks: hooks})
		_, _ = manager.Load(context.Background())
		_ = manager.Flush(context.Background())
		_, statErr := os.Stat(path)
		observations = append(observations,
			observation{"writes without metadata change", strings.Repeat("w", len(hooks.take())), "", "1b durable control always persists at startup"},
			observation{"file exists", boolText(statErr == nil), "false", "1b durable control always persists at startup"},
		)
	})

	for _, observation := range observations {
		requireCtlText(t, observation.label, observation.got, observation.want, observation.changesBy)
	}
}

func boolText(value bool) string {
	if value {
		return "true"
	}
	return "false"
}

func ctlSorted(values []string) []string {
	out := append([]string(nil), values...)
	for i := 1; i < len(out); i++ {
		for j := i; j > 0 && out[j] < out[j-1]; j-- {
			out[j], out[j-1] = out[j-1], out[j]
		}
	}
	return out
}
